    public override string Retrieve(double[,] harmonizedData, int originalLength)
    {
        try
        {
            // Extract binary values from the harmonized matrix
            string reconstructedBinary = string.Join(string.Empty,
                harmonizedData.Cast<double>().Take(originalLength).Select(bit => ((int)Math.Round(bit)).ToString()));

            // Convert binary back to text
            return BinaryToText(reconstructedBinary);
        }
        catch
        {
            return "Reconstruction Error";
        }
    }

    // Convert text to binary representation
    private string TextToBinary(string text)
    {
        return string.Join(string.Empty, text.Select(c => Convert.ToString(c, 2).PadLeft(8, '0')));
    }

    // Convert binary representation back to text
    private string BinaryToText(string binary)
    {
        try
        {
            List<byte> bytes = new List<byte>();
            for (int i = 0; i < binary.Length; i += 8)
            {
                bytes.Add(Convert.ToByte(binary.Substring(i, 8), 2));
            }
            return Encoding.UTF8.GetString(bytes.ToArray());
        }
        catch
        {
            return "Decoding Error";
        }
    }
}

